function renderEpisodes(episodes) {
  const episodesContainer = document.getElementById("episodes");
  episodesContainer.innerHTML = ""; // Clear the container

  episodes.forEach((episode) => {
    const row = document.createElement("div");
    row.className = "episode"; // Use the exact class name
    row.dataset.audio = episode.audioUrl;
    row.dataset.title = episode.title;
    row.dataset.art = episode.imageUrl;

    const img = document.createElement("img");
    img.src = episode.imageUrl;
    img.alt = ""; // Decorative image, not a text alternative

    row.appendChild(img);

    const title = document.createElement("h3");
    title.textContent = episode.title;

    const pubDate = document.createElement("p");
    pubDate.textContent = "Published: " + episode.pubDate;

    const ethosBadge = document.createElement("span");
    ethosBadge.className = "ethos-badge";
    ethosBadge.style.backgroundColor = episode.ethos === "pass" ? "green" : episode.ethos === "conflict" ? "red" : "gray";

    row.appendChild(title);
    row.appendChild(pubDate);
    row.appendChild(ethosBadge);
    episodesContainer.appendChild(row);
  });
}

