function subscribe() {
  const feedUrl = document.getElementById("feed-url").value;
  fetch(`/api/subscribe?url=${encodeURIComponent(feedUrl)}`)
    .then(response => {
      if (response.ok) {
        return response.json();
      } else {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
    })
    .then(data => {
      if (data.show) {
        renderEpisodes(data.episodes);
      } else {
        // Show an error message
        document.getElementById("episodes").textContent = "Error: Unable to subscribe to the feed.";
      }
    })
    .catch(error => {
      console.error("Error fetching data:", error);
      document.getElementById("episodes").textContent = "Error: Unable to subscribe to the feed.";
    });
}

